def _backfill() -> None:
    """Data step. Two things only:
    1. search_profile.tracks from the existing flat roles (one track, variants suggested);
    2. job.matched_track / matched_role for existing jobs, only where empty.
    No score, label, stage, note or other job column is touched."""
    import json

    from app.services.roles import match_track, with_suggested_variants

    conn = op.get_bind()
    years = None
    row = conn.exec_driver_sql("select value from app_setting where key = 'profile'").first()
    if row:
        value = json.loads(row[0]) if isinstance(row[0], str) else row[0]
        years = value.get('years_experience')
    tracks_by_profile = {}
    for pid, roles, tracks in conn.exec_driver_sql(
        'select id, roles, tracks from search_profile'
    ).all():
        roles = json.loads(roles) if isinstance(roles, str) else (roles or [])
        tracks = json.loads(tracks) if isinstance(tracks, str) else (tracks or [])
        if not tracks and roles:
            tracks = with_suggested_variants(
                [{'name': 'Data/AI', 'years_experience': years, 'roles': [{'title': r} for r in roles]}]
            )
            conn.exec_driver_sql(
                'update search_profile set tracks = ? where id = ?', (json.dumps(tracks), pid)
            )
        tracks_by_profile[pid] = tracks
    active = conn.exec_driver_sql('select id from search_profile where is_active = 1').first()
    tracks = tracks_by_profile.get(active[0]) if active else None
    if not tracks:
        return
    for job_id, title in conn.exec_driver_sql(
        'select id, title from job where matched_track is null and matched_role is null'
    ).all():
        hit = match_track(title or '', tracks)
        if hit:
            conn.exec_driver_sql(
                'update job set matched_track = ?, matched_role = ? where id = ?',
                (hit[0], hit[1], job_id),
            )


